package com.lqq.supportflow.conversation.infrastructure.events;
import com.lqq.supportflow.conversation.domain.*; import java.util.*; import java.util.concurrent.*; import java.util.concurrent.atomic.AtomicLong; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component;
@Component @ConditionalOnProperty(prefix="supportflow.generation.redis",name="enabled",havingValue="false",matchIfMissing=true) public class InMemoryGenerationEventStore implements GenerationEventStore { private final AtomicLong sequence=new AtomicLong(); private final ConcurrentMap<Long,List<GenerationEvent>> events=new ConcurrentHashMap<>(); public void append(Long generationId,String type,String data){events.computeIfAbsent(generationId,ignored->new CopyOnWriteArrayList<>()).add(new GenerationEvent(Long.toString(sequence.incrementAndGet()),type,data));} public void appendIfAbsent(Long generationId,String type,String data){List<GenerationEvent> stream=events.computeIfAbsent(generationId,ignored->new CopyOnWriteArrayList<>());if(stream.stream().noneMatch(event->event.type().equals(type)))stream.add(new GenerationEvent(Long.toString(sequence.incrementAndGet()),type,data));} public List<GenerationEvent> readAfter(Long generationId,String lastEventId){long last=lastEventId==null||lastEventId.isBlank()?0:Long.parseLong(lastEventId);return events.getOrDefault(generationId,List.of()).stream().filter(event->Long.parseLong(event.id())>last).toList();}}
